 				/* add imm, %rsp */
 				state->stack_size -= op->src.offset;
 				if (cfa->base == CFI_SP)
 					cfa->offset -= op->src.offset;
 				break;
 			}

 			if (op->dest.reg == CFI_SP && op->src.reg == CFI_BP) {

 				/* lea disp(%rbp), %rsp */
 				state->stack_size = -(op->src.offset + regs[CFI_BP].offset);
